 "content": "from collections import Counter


def transform(grid):
    """Replace each isolated marker with the five-cell horizontal template."""
    h, w = len(grid), len(grid[0])
    counts = Counter(v for row in grid for v in row)
    background = counts.most_common(1)[0][0]

    # The template is the contiguous five-cell non-background run.
    template = None
    template_cells = set()
    for r, row in enumerate(grid):
        c = 0
        while c < w:
            if row[c] == background:
                c += 1
                continue
            start = c
            while c < w and row[c] != background:
                c += 1
            if c - start == 5:
                template = row[start:c]
                template_cells = {(r, x) for x in range(start, c)}
                break
        if template is not None:
            break
    if template is None:
        return [row[:] for row in grid]

    other_counts = Counter(
        v for r, row in enumerate(grid) for c, v in enumerate(row)
        if v != background and (r, c) not in template_cells
    )
    marker = other_counts.most_common(1)[0][0]
    out = [row[:] for row in grid]
    for r in range(h):
        for c in range(w):
            if grid[r][c] == marker and (r, c) not in template_cells:
                start = c - 2
                for k, color in enumerate(template):
                    x = start + k
                    if 0 <= x < w:
                        out[r][x] = color
    return out
